"""Camera-guided controller for the single select_billiards episode.
Only Robot spec, images, depth, and proprioception are used. No resets.
"""
import json,time,argparse
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation as R
from rcb_client import Robot
from kin import fk,ik,LIMITS
OUT=Path('/app/output');OUT.mkdir(exist_ok=True)
r=Robot()
DOWN=R.from_euler('xyz',[np.pi,0,np.pi/2]).as_matrix()
def save(res,label):
 res.save(OUT/label)
 (OUT/'current.json').write_text(json.dumps(res.meta,indent=2))
 print(label,json.dumps({k:res.meta.get(k) for k in ['control_steps','done','reason','clipped']}))
 print('state',np.round(res.meta['proprio']['now'][:7],5),'tcp',np.round(res.meta['proprio']['now'][16:23],5),'finger',np.round(res.meta['proprio']['now'][14:16],5))
 return res

def obs(label='obs',depth=True):
 return save(r.get_obs(include_depth=depth,video='none'),label)

def joint(q,finger=.04,duration=3,label='move',cameras=None):
 o=r.get_obs(cameras=[],video='none');now=np.array(o.meta['proprio']['now']);start=now[23:32]
 goal=np.r_[q,finger,finger];assert np.all(q>=LIMITS[:,0]) and np.all(q<=LIMITS[:,1])
 n=round(duration/.1);t=np.linspace(0,1,n);smooth=3*t*t-2*t*t*t;A=start+(goal-start)*smooth[:,None]
 # Persist every command before it is sent, making this single episode reproducible.
 with open(OUT/'actions.jsonl','a') as f:f.write(json.dumps({'label':label,'dt':.1,'actions':A.tolist()})+'\n')
 return save(r.submit('joint_position',A,dt=.1,cameras=cameras,video='none',include_depth=True,note=label),label)

def move(p,finger=.04,duration=3,label='move',rot=DOWN):
 o=r.get_obs(cameras=[],video='none');q=np.array(o.meta['proprio']['now'][:7]);goal=ik(p,rot,q)
 print('goal',p,'q',goal,'fk',fk(goal)[0])
 return joint(goal,finger,duration,label)

if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('mode',choices=['observe','move','joint','replay']);ap.add_argument('--p',nargs=3,type=float);ap.add_argument('--q',nargs=7,type=float);ap.add_argument('--finger',type=float,default=.04);ap.add_argument('--duration',type=float,default=3);ap.add_argument('--label',default='obs');a=ap.parse_args()
 if a.mode=='observe':obs(a.label)
 elif a.mode=='move':move(a.p,a.finger,a.duration,a.label)
 elif a.mode=='joint':joint(np.array(a.q),a.finger,a.duration,a.label)
 elif a.mode=='replay':
  for line in (OUT/'actions.jsonl').read_text().splitlines():
   row=json.loads(line);res=r.submit('joint_position',row['actions'],dt=row['dt'],cameras=[],video='none',note=row['label'])
   if res.done:break
